class Solution:
    def numberOfCombinations(self, num: str) -> int:
        import sys
        from functools import lru_cache
        sys.setrecursionlimit(len(num) + 10)
        MOD = 10 ** 9 + 7
        n = len(num)

        @lru_cache(maxsize=None)
        def dfs(i, plen):
            if i == n:
                return 1
            if num[i] == '0':
                return 0
            total = 0
            for l in range(max(plen, 1), n - i + 1):
                if l == plen and num[i - plen:i] > num[i:i + l]:
                    continue
                total = (total + dfs(i + l, l)) % MOD
            return total

        return dfs(0, 0)

