class Solution {
public:
    int numberOfCombinations(string num) {
        const int MOD = 1e9 + 7;
        int n = num.size();
        vector<vector<int>> memo(n + 1, vector<int>(n + 1, -1));
        function<int(int, int)> dfs = [&](int i, int plen) -> int {
            if (i == n) return 1;
            if (num[i] == '0') return 0;
            int& res = memo[i][plen];
            if (res != -1) return res;
            long long total = 0;
            for (int l = max(plen, 1); l <= n - i; l++) {
                if (l == plen && num.compare(i - plen, plen, num, i, l) > 0) continue;
                total += dfs(i + l, l);
            }
            return res = (int)(total % MOD);
        };
        return dfs(0, 0);
    }
};

