class Solution {
    private String num;
    private int[][] memo;

    public int numberOfCombinations(String num) {
        this.num = num;
        int n = num.length();
        memo = new int[n + 1][n + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(0, 0);
    }

    private int dfs(int i, int plen) {
        int n = num.length();
        if (i == n) return 1;
        if (num.charAt(i) == '0') return 0;
        if (memo[i][plen] != -1) return memo[i][plen];
        long total = 0;
        for (int l = Math.max(plen, 1); l <= n - i; l++) {
            if (l == plen && num.substring(i - plen, i).compareTo(num.substring(i, i + l)) > 0) continue;
            total += dfs(i + l, l);
        }
        return memo[i][plen] = (int) (total % 1_000_000_007);
    }
}

