    const n = num.length;
    const memo = new Map();
    const dfs = (i, plen) => {
        if (i === n) return 1;
        if (num[i] === '0') return 0;
        const key = i * (n + 1) + plen;
        if (memo.has(key)) return memo.get(key);
        let total = 0;
