class Solution:
    def numberOfCombinations(self, num: str) -> int:
        MOD = 10 ** 9 + 7
        n = len(num)
        if num[0] == '0':
            return 0
        lcp = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            li, ln, ci = lcp[i], lcp[i + 1], num[i]
            for j in range(n - 1, i, -1):
                if ci == num[j]:
                    li[j] = ln[j + 1] + 1
        Q = [[0] * (n + 2) for _ in range(n)]
        for i in range(n - 1, -1, -1):
            if num[i] == '0':
                continue
            Qi = Q[i]
            suf = 0
            for l in range(n - i, 0, -1):
                j = i + l
                if j == n:
                    cur = 1
                else:
                    Qj = Q[j]
                    cur = Qj[l + 1]
                    if j + l <= n:
                        c = lcp[i][j]
                        if c >= l or num[i + c] < num[j + c]:
                            cur = (cur + Qj[l] - Qj[l + 1]) % MOD
                suf = (suf + cur) % MOD
                Qi[l] = suf
        return Q[0][1]

