var numberOfCombinations = function(num) {
    const MOD = 1000000007;
    const n = num.length;
    if (num[0] === '0') return 0;
    const W = n + 2;
    const lcp = new Int32Array((n + 1) * (n + 1));
    for (let i = n - 1; i >= 0; i--)
        for (let j = n - 1; j > i; j--)
            if (num[i] === num[j]) lcp[i * (n + 1) + j] = lcp[(i + 1) * (n + 1) + j + 1] + 1;
    const Q = new Int32Array(n * W);
    for (let i = n - 1; i >= 0; i--) {
        if (num[i] === '0') continue;
        let suf = 0;
        for (let l = n - i; l >= 1; l--) {
            const j = i + l;
            let cur;
            if (j === n) cur = 1;
            else {
                cur = Q[j * W + l + 1];
                if (j + l <= n) {
                    const c = lcp[i * (n + 1) + j];
                    if (c >= l || num[i + c] < num[j + c])
                        cur = (cur + Q[j * W + l] - Q[j * W + l + 1] + MOD) % MOD;
                }
            }
            suf = (suf + cur) % MOD;
            Q[i * W + l] = suf;
        }
    }
    return Q[1];
};
